namespace Smidgenomics.Unity.Bookmarks.Editor
{
	using System;
	using System.Collections.Generic;
	using System.Runtime.Serialization;
	using Newtonsoft.Json;
	using UnityEditor;

	/// <summary>
	/// Query used to filter assets in DB
	/// Assets:https://docs.unity3d.com/ScriptReference/AssetDatabase.FindAssets.html
	/// </summary>
	[Serializable]
	[JsonObject(MemberSerialization.OptIn)]
	internal sealed class BKQuery
	{
		// Get asset guids or paths generated by query
		public string[] GetIncludes()
		{
			return _includesGetter.Invoke();
		}

		[OnDeserialized]
		private void OnDeserialized(StreamingContext context)
		{
			if (_folders is not { Length: > 0 })
			{
				return;
			}
			
			if (_filter.Contains('*'))
			{
				_includesGetter = GetFilePathsWildcard;
			}
			else
			{
				_includesGetter = GetAssetGUIDs;
			}
		}

		// search pattern
		[JsonProperty("filter")] private string _filter = string.Empty;

		// Folders to search
		[JsonProperty("folders")]
		private string[] _folders = Array.Empty<string>();

		private string[] GetFilePathsWildcard()
		{
			List<string> paths = new();
			foreach (var folder in _folders)
			{
				var files = BKUtils.ListFiles(folder, _filter, true);

				foreach (var file in files)
				{
					paths.Add(file.Replace(@"\", "/"));
				}
				
			}
			return paths.ToArray();
		}

		private string[] GetAssetGUIDs()
		{
			return AssetDatabase.FindAssets(_filter, _folders);
		}
		
		private static string[] EmptyGetter() => Array.Empty<string>();

		private Func<string[]> _includesGetter = EmptyGetter;

	}
}